krpano.action:
set(global.skyline_editor_active, false);
set(global.skyline_counter, 1);
set(global.skyline_selected, null);
set(global.skyline_drag_mode, false);
set(global.skyline_arrow_height, 80);

if(global.skyline_editor_active == true,
	set(global.skyline_editor_active, false);
	set(layer[skyline_editor_panel].visible, false);
	trace('Skyline Editor CHIUSO');
,
	set(global.skyline_editor_active, true);
	set(layer[skyline_editor_panel].visible, true);
	trace('Skyline Editor APERTO - Usa i pulsanti per aggiungere etichette');
);

txtadd(hotspot_name, 'skyline_label_', get(global.skyline_counter));

addhotspot(get(hotspot_name));
set(hotspot[get(hotspot_name)].type, text);
set(hotspot[get(hotspot_name)].distorted, true);
set(hotspot[get(hotspot_name)].capture, false);
set(hotspot[get(hotspot_name)].enabled, false);
set(hotspot[get(hotspot_name)].width, 220);
set(hotspot[get(hotspot_name)].height, 120);
set(hotspot[get(hotspot_name)].css, 'text-align:center; color:#FFFFFF; font-family:Arial,sans-serif; font-size:14px; text-shadow: 2px 2px 4px #000000;');
set(hotspot[get(hotspot_name)].bgcolor, 0x000000);
set(hotspot[get(hotspot_name)].bgalpha, 0.0);
set(hotspot[get(hotspot_name)].edge, center);
set(hotspot[get(hotspot_name)].zorder, 100);

copy(hotspot[get(hotspot_name)].ath, view.hlookat);
copy(hotspot[get(hotspot_name)].atv, view.vlookat);

txtadd(label_text, 'ETICHETTA ', get(global.skyline_counter));
copy(arrow_height, global.skyline_arrow_height);
txtadd(html_content, '[div style="text-align:center;display:flex;flex-direction:column;align-items:center;"][span style="font-size:12px;opacity:0.9;display:block;margin-bottom:2px;"]1.5km - 3 min[br/]800m - 15 min[/span][b style="font-size:18px;display:block;margin-bottom:8px;"]', get(label_text), '[/b][img src="hotspots/arrow_down.svg" style="display:block;width:30px;height:', get(arrow_height), 'px;"][/img][/div]');
set(hotspot[get(hotspot_name)].html, get(html_content));

txtadd(marker_name, 'skyline_marker_', get(global.skyline_counter));
addhotspot(get(marker_name));
set(hotspot[get(marker_name)].url, 'hotspots/info.svg');
set(hotspot[get(marker_name)].scale, 0.3);
set(hotspot[get(marker_name)].alpha, 0.0);
set(hotspot[get(marker_name)].edge, center);
set(hotspot[get(marker_name)].capture, true);
set(hotspot[get(marker_name)].handcursor, true);
set(hotspot[get(marker_name)].zorder, 1000);
copy(hotspot[get(marker_name)].ath, hotspot[get(hotspot_name)].ath);
copy(hotspot[get(marker_name)].atv, hotspot[get(hotspot_name)].atv);

txtadd(marker_onclick, 'select_skyline_label(', get(hotspot_name), ');');
set(hotspot[get(marker_name)].onclick, get(marker_onclick));
set(hotspot[get(marker_name)].ondown, 'set(global.skyline_drag_mode, true); start_drag_skyline();');
set(hotspot[get(marker_name)].onup, 'stop_drag_skyline();');

set(hotspot[get(hotspot_name)].marker_name, get(marker_name));
set(hotspot[get(marker_name)].label_name, get(hotspot_name));

inc(global.skyline_counter);

txtadd(msg, 'Etichetta ', get(label_text), ' aggiunta! Trascinala per posizionarla.');
trace(get(msg));
set(layer[skyline_info_text].html, get(msg));

set(global.skyline_selected, %1);

forall(hotspot, hs,
	if(indexof(hs.name, 'skyline_marker_') == 0,
		if(hs.label_name == %1,
			set(hs.alpha, 1.0);
			set(hs.scale, 0.4);
		,
			set(hs.alpha, 0.7);
			set(hs.scale, 0.3);
		);
	);
);

trace('Etichetta selezionata: %1');
set(layer[skyline_info_text].html, 'Selezionata: %1 - Trascina il marker per spostarla');

copy(global.skyline_dragging, name);
asyncloop(global.skyline_drag_mode, 
	copy(marker_name, global.skyline_dragging);
	screentosphere(mouse.x, mouse.y, new_ath, new_atv);
	set(hotspot[get(marker_name)].ath, get(new_ath));
	set(hotspot[get(marker_name)].atv, get(new_atv));
	copy(label_name, hotspot[get(marker_name)].label_name);
	set(hotspot[get(label_name)].ath, get(new_ath));
	set(hotspot[get(label_name)].atv, get(new_atv));
);

if(global.skyline_selected != null,
	copy(hs_name, global.skyline_selected);
	copy(hs_ath, hotspot[get(hs_name)].ath);
	copy(hs_atv, hotspot[get(hs_name)].atv);
	copy(hs_html, hotspot[get(hs_name)].html);

	trace('========================================');
	trace('CODICE ETICHETTA SKYLINE');
	trace('========================================');
	trace('Copia questo codice nella scena desiderata:');
	trace('');
	calc(line1, '<hotspot name="' + get(hs_name) + '"');
	trace(get(line1));
	trace('         style="skyline_label"');
	calc(line2, '         ath="' + get(hs_ath) + '"');
	trace(get(line2));
	calc(line3, '         atv="' + get(hs_atv) + '"');
	trace(get(line3));
	calc(line4, '         html="' + get(hs_html) + '"');
	trace(get(line4));
	trace('/>');
	trace('');
	trace('========================================');

	txtadd(output, 'ATH: ', get(hs_ath), '[br/]ATV: ', get(hs_atv), '[br/]Nome: ', get(hs_name), '[br/]Vedi console F12 per codice completo');
	set(layer[skyline_code_output].html, get(output));
	set(layer[skyline_code_output].visible, true);
	set(layer[skyline_info_text].html, 'Codice copiato nella console! Premi F12 per vederlo.');
,
	trace('ERRORE: Nessuna etichetta selezionata');
	set(layer[skyline_info_text].html, 'ERRORE: Seleziona prima una etichetta!');
);

if(global.skyline_selected != null,
	copy(hs_name, global.skyline_selected);
	copy(marker_name, hotspot[get(hs_name)].marker_name);

	removehotspot(get(hs_name));
	removehotspot(get(marker_name));

	set(global.skyline_selected, null);

	trace(calc('Etichetta ' + hs_name + ' eliminata'));
	set(layer[skyline_info_text].html, calc('Etichetta ' + hs_name + ' eliminata'));
,
	trace('ERRORE: Nessuna etichetta selezionata');
	set(layer[skyline_info_text].html, 'ERRORE: Seleziona prima una etichetta!');
);

forall(hotspot, hs,
	if(indexof(hs.name, 'skyline_marker_') == 0,
		set(hs.visible, false);
	);
);
set(layer[skyline_info_text].html, 'Marker nascosti - Solo etichette visibili');

forall(hotspot, hs,
	if(indexof(hs.name, 'skyline_marker_') == 0,
		set(hs.visible, true);
	);
);
set(layer[skyline_info_text].html, 'Marker visibili');

calc(global.skyline_arrow_height, global.skyline_arrow_height + 10);
if(global.skyline_arrow_height GT 800, set(global.skyline_arrow_height, 800));
txtadd(msg, 'Altezza freccia: ', get(global.skyline_arrow_height), 'px');
set(layer[skyline_info_text].html, get(msg));
set(layer[arrow_height_value].html, calc(global.skyline_arrow_height + 'px'));

calc(global.skyline_arrow_height, global.skyline_arrow_height - 10);
if(global.skyline_arrow_height LT 20, set(global.skyline_arrow_height, 20));
txtadd(msg, 'Altezza freccia: ', get(global.skyline_arrow_height), 'px');
set(layer[skyline_info_text].html, get(msg));
set(layer[arrow_height_value].html, calc(global.skyline_arrow_height + 'px'));
